/*
 * Store the last row's value, mapping SQL NULL to the
 * null value and anything else to a string.
 */
if (PQgetisnull(res, ntuples - 1, fld))
{
	PgBenchValue nullval;

	setNullValue(&nullval);
	ok = putVariableValue(&st->variables,
						  meta == META_ASET ? "aset" : "gset",
						  varname, &nullval);
}
else
	ok = putVariable(&st->variables,
					 meta == META_ASET ? "aset" : "gset",
					 varname,
					 PQgetvalue(res, ntuples - 1, fld));

/* Assign a value to a variable, creating it if need be */
/* Returns false on failure (bad name) */
static bool
putVariableValue(Variables *variables, const char *context, char *name,
				 const PgBenchValue *value)
{
	Variable   *var;

	var = lookupCreateVariable(variables, context, name);
	if (!var)
		return false;

	free(var->svalue);
	var->svalue = NULL;
	var->value = *value;

	return true;
}

makeVariableValue(Variable *var)
{
	size_t		slen;

	if (var->value.type != PGBT_NO_VALUE)
		return true;			/* no work */

	slen = strlen(var->svalue);

	if (slen == 0)
		/* what should it do on ""? */
		return false;

	if (pg_strcasecmp(var->svalue, "null") == 0)
	{
		setNullValue(&var->value);
	}

if (var->svalue)
	return var->svalue;		/* we have it in string form */

/* We need to produce a string equivalent of the value */
Assert(var->value.type != PGBT_NO_VALUE);
if (var->value.type == PGBT_NULL)
	snprintf(stringform, sizeof(stringform), "NULL");
else if (var->value.type == PGBT_BOOLEAN)
	snprintf(stringform, sizeof(stringform),
			 "%s", var->value.u.bval ? "true" : "false");
else if (var->value.type == PGBT_INT)
	snprintf(stringform, sizeof(stringform),
			 INT64_FORMAT, var->value.u.ival);
else if (var->value.type == PGBT_DOUBLE)
	snprintf(stringform, sizeof(stringform),
			 "%.*g", DBL_DIG, var->value.u.dval);
else						/* internal error, unexpected type */
	Assert(0);
var->svalue = pg_strdup(stringform);
return var->svalue;

/* Reset was-newline flag */
last_was_newline = false;

/*
 * On the first call for a \sleep argument, emit the mode-selection
 * token that makes the grammar accept a time unit after the
 * expression.
 */
if (sleep_expr_pending)
{
	sleep_expr_pending = false;
	return MODE_SLEEP_EXPR;
}

result: expr				{
								*expr_parse_result_p = $1;
								(void) yynerrs; /* suppress compiler warning */
							}
	| MODE_SLEEP_EXPR expr opt_unit
							{
								/* scale the \sleep duration to microseconds */
								*expr_parse_result_p =
									make_op(yyscanner, "*", $2,
											make_integer_constant($3));
							}
	;

/*
 * The optional time unit of a \sleep duration reaches us as a FUNCTION
 * token, being just an identifier; translate it to the corresponding
 * microsecond multiplier.  A bare FUNCTION can never follow a complete
 * expression otherwise, so this introduces no grammar conflicts.
 */
opt_unit: /* EMPTY, defaults to seconds */
							{ $$ = INT64CONST(1000000); }
	| FUNCTION				{
								if (pg_strcasecmp($1, "us") == 0)
									$$ = INT64CONST(1);
								else if (pg_strcasecmp($1, "ms") == 0)
									$$ = INT64CONST(1000);
								else if (pg_strcasecmp($1, "s") == 0)
									$$ = INT64CONST(1000000);
								else
									expr_yyerror_more(yyscanner, "unrecognized time unit, must be us, ms or s",
													  $1);
								pg_free($1);
							}
	;

/*
 * Evaluate the delay expression of a \sleep command, and return the
 * requested amount of delay, in microseconds.  Returns true on success,
 * false on error.
 */
static bool
evaluateSleep(CState *st, Command *command, int64 *usecs)
{
	PgBenchValue result;
	int64		usec;

	if (!evaluateExpr(st, command->expr, &result) ||
		!coerceToInt(&result, &usec))
		return false;

	/* historically, a negative duration just means no sleep */
	if (usec < 0)
		usec = 0;

	*usecs = usec;
	return true;
}

if (command->meta == META_SLEEP)
{
	int64		usec;

	/*
	 * A \sleep doesn't execute anything, we just get the delay from the
	 * argument, and enter the CSTATE_SLEEP state.  (The per-command
	 * latency will be recorded in CSTATE_SLEEP state, not here, after the
	 * delay has elapsed.)
	 */
	if (!evaluateSleep(st, command, &usec))
	{
		commandFailed(st, "sleep", "execution of meta-command failed");
		return CSTATE_ABORTED;
	}

	pg_time_now_lazy(now);
	/* an absurd duration saturates rather than wrapping to the past */
	if (pg_add_s64_overflow(*now, usec, &st->sleep_until))
		st->sleep_until = PG_INT64_MAX;
	return CSTATE_SLEEP;
}

else if (command->meta == META_WHILE)
{
	PgBenchExpr *expr = command->expr;
	PgBenchValue result;

	Assert(command->jump_target >= 0);

	if (timer_exceeded)
	{
		/*
		 * Once the run duration has expired, treat the condition as false
		 * without evaluating it, so that no new iteration can start.
		 * timer_exceeded is never reset during a run, so from then on
		 * every loop reached, including one entered by the backward jump
		 * of an \endwhile, exits immediately: nested loops unwind and the
		 * rest of the script executes normally down to CSTATE_END_TX,
		 * whose regular timer check finishes the client.  This is what
		 * makes -T work on a loop containing only meta commands, which
		 * has no other reason to stop.
		 */
		st->pending_jump = command->jump_target;
	}

	else
	{
		if (!evaluateExpr(st, expr, &result))
		{
			commandFailed(st, argv[0], "evaluation of meta-command failed");
			return CSTATE_ABORTED;
		}

		if (!valueTruth(&result))
			st->pending_jump = command->jump_target;
	}
}
else if (command->meta == META_ENDWHILE)
{
	Assert(command->jump_target >= 0);

	/* jump back to the \while, which re-evaluates its condition */
	st->pending_jump = command->jump_target;
}

/* Go ahead with next command, to be executed or skipped */
if (st->pending_jump >= 0)
{
	bool		backward = st->pending_jump <= st->command;

	/* deferred jump of a \while or \endwhile */
	st->command = st->pending_jump;
	st->pending_jump = -1;
	st->state = conditional_active(st->cstack) ?
		CSTATE_START_COMMAND : CSTATE_SKIP_COMMAND;

	/*
	 * Return on a backward jump, so that a loop whose body
	 * has no command yielding to the thread loop, such as one
	 * containing only meta commands, does not monopolize its
	 * thread and starve the other clients of it.
	 */
	if (backward)
		return;
	break;
}
st->command++;

case META_ENDWHILE:
	if (depth == 0)
		ConditionError(ps->desc, i + 1, "\\endwhile without matching \\while");
	if (!stack[depth - 1].is_while)
		ConditionError(ps->desc, i + 1,
					   openBlockOfKind(stack, depth, true) ?
					   "\\endwhile without matching \\while inside this \\if branch" :
					   "\\endwhile without matching \\while");
	depth--;

	/*
	 * Cross-link the pair: the \while jumps past this command
	 * when its condition is false, and this command jumps back to
	 * the \while.
	 */
	ps->commands[stack[depth].command]->jump_target = i + 1;
	cmd->jump_target = stack[depth].command;
	break;

static void
processXactStats(TState *thread, CState *st, pg_time_usec_t *now,
				 bool skipped, StatsData *agg)
{
	double		latency = 0.0,
				lag = 0.0;
	bool		detailed = progress || throttle_delay || latency_limit ||
		use_log || per_script_stats || num_latency_percentiles > 0;

	if (detailed && !skipped && st->estatus == ESTATUS_NO_ERROR)
	{
		pg_time_now_lazy(now);

		/* compute latency & lag */
		latency = (*now) - st->txn_scheduled;
		lag = st->txn_begin - st->txn_scheduled;
	}

	/* keep detailed thread stats */
	accumStats(&thread->stats, skipped, latency, lag, st->estatus, st->tries);

switch (estatus)
{
		/* Record the successful transaction */
	case ESTATUS_NO_ERROR:
		stats->cnt++;

		addToSimpleStats(&stats->latency, lat);

		if (num_latency_percentiles > 0)
			stats->latency_histogram[latencyHistBucket(lat)]++;

		/* and possibly the same for schedule lag */
		if (throttle_delay)
			addToSimpleStats(&stats->lag, lag);
		break;

static int
latencyHistBucket(double latency)
{
	int64		v = (int64) latency;
	int			k;

	if (v < (1 << LATENCY_HIST_SUBBITS))
		return (v < 0) ? 0 : (int) v;

	k = pg_leftmost_one_pos64((uint64) v);
	if (k >= LATENCY_HIST_MAXBITS)
		return LATENCY_HIST_NBUCKETS - 1;	/* overflow bucket */

	return ((k - LATENCY_HIST_SUBBITS + 1) << LATENCY_HIST_SUBBITS) |
		((int) (v >> (k - LATENCY_HIST_SUBBITS)) &
		 ((1 << LATENCY_HIST_SUBBITS) - 1));
}

exact = latency_percentiles[i] * (double) total / 100.0;
rank = (int64) ceil(exact - 1e-9 * exact);
rank = Max(rank, 1);
rank = Min(rank, total);

for (idx = 0; idx < LATENCY_HIST_NBUCKETS; idx++)
{
	cum += histogram[idx];
	if (cum >= rank)
		break;
}

printf("%s p%.10g = ", (i > 0) ? "," : "", latency_percentiles[i]);
if (idx == LATENCY_HIST_NBUCKETS - 1)
	printf("> %.3f ms",
		   0.001 * (double) ((int64) 1 << LATENCY_HIST_MAXBITS));
else
	printf("%.3f ms", 0.001 * latencyHistBucketMidpoint(idx));

if (throttle_delay || progress || latency_limit ||
	num_latency_percentiles > 0)
	printSimpleStats("latency", &total->latency);
else
{
	/* no measurement, show average latency computed from run time */
	printf("latency average = %.3f ms%s\n",
		   0.001 * total_duration * nclients / total_cnt,
		   failures > 0 ? " (including failures)" : "");
}

if (num_latency_percentiles > 0)
{
	if (latencyHistTotal(total->latency_histogram) > 0)
		printLatencyPercentiles("latency", total->latency_histogram);
	else
		printf("latency percentiles: (no successful transactions)\n");
}

/*
 * Return whether statistics recorded now belong to the --warmup period and
 * must be diverted to the thread's warmup bucket.  Reads the clock (lazily)
 * while warmup is running; the boundary is judged on the recording time, so
 * a transaction straddling it is measured in full.
 */
static bool
warmupActive(TState *thread, pg_time_usec_t *now)
{
	if (warmup == 0 || thread->warmup_done)
		return false;

	pg_time_now_lazy(now);
	if (*now < thread->warmup_until)
		return true;

	thread->warmup_done = true;
	thread->warmup_conn_duration = thread->conn_duration;
	return false;
}

if (in_warmup)
{
	/* stats of warmup transactions go to the discard bucket */
	accumStats(&thread->warmup_stats, skipped, latency, lag, st->estatus,
			   st->tries);
}
else
{
	/* keep detailed thread stats */
	accumStats(&thread->stats, skipped, latency, lag, st->estatus,
			   st->tries);

	/* count transactions over the latency limit, if needed */
	if (latency_limit && latency > latency_limit)
		thread->latency_late++;
}

case CSTATE_END_COMMAND:

	/*
	 * command completed: accumulate per-command execution times
	 * in thread-local data structure, if per-command latencies
	 * are requested.
	 */
	if (report_per_command)
	{
		pg_time_now_lazy(&now);

		command = sql_script[st->use_file].commands[st->command];
		/* XXX could use a mutex here, but we choose not to */
		if (!warmupActive(thread, &now))
			addToSimpleStats(&command->stats,
							 PG_TIME_GET_DOUBLE(now - st->stmt_begin));
	}

initStats(&cur, 0);
for (int i = 0; i < nthreads; i++)
{
	mergeStats(&cur, &threads[i].stats);

	/*
	 * Transactions diverted to the warmup bucket still count for live
	 * progress reporting.
	 */
	if (warmup > 0)
		mergeStats(&cur, &threads[i].warmup_stats);
}

total_duration = pg_time_now() - bench_start - (int64) 1000000 * warmup;
if (total_duration < 1)
	total_duration = 1;

printResults(&stats, &warmup_stats, total_duration, conn_total_duration,
			 bench_start - start_time, latency_late);
